## solutions

#### iterative

```cpp
Node* createLinkedList(std::vector<std::string> values) {
  Node* dummyHead = new Node("");
  Node* tail = dummyHead;

  for (std::string val : values) {
    tail->next = new Node(val);
    tail = tail->next;
  }

  return dummyHead->next;
}
```

- n = length of values
- Time: O(n)
- Space: O(n)

#### recursive

```cpp
Node* createLinkedList(std::vector<std::string> &values, int idx) {
 if (idx == values.size()) {
   return nullptr;
 }

  Node* head = new Node(values[idx]);
  head->next = createLinkedList(values, idx + 1);
  return head;
}

Node* createLinkedList(std::vector<std::string> values) {
  return createLinkedList(values, 0);
}
```

- n = length of values
- Time: O(n)
- Space: O(n)
